INSERT INTO `contact_submissions` (`id`, `name`, `email`, `phone`, `message`, `created_at`) VALUES ('6835914f50804c7413b8fc3a3b0bfca1', 'Senx', 'senx.roel@gmail.com', '2102102101', 'Hello youngover60.com,\r\n\r\nI recently reviewed your website youngover60.com and noticed a few SEO-related issues that may be affecting your Google rankings, website traffic, and overall online visibility.\r\n\r\nWould you like me to send a screenshot highlighting these issues? I can also prepare a detailed SEO audit report, along with recommendations, proposal, and pricing to help improve your website’s search engine performance and generate more potential leads.\r\n\r\nLooking forward to your response.\r\n\r\nKind regards,', '2026-06-29 09:11:36');

