  CONSTRAINT `page_revisions_ibfk_1` FOREIGN KEY (`page_id`) REFERENCES `custom_pages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `page_revisions` (`id`, `page_id`, `title_en`, `title_nl`, `title_ar`, `content_en`, `content_nl`, `content_ar`, `excerpt_en`, `excerpt_nl`, `excerpt_ar`, `template_type`, `sort_order`, `show_in_menu`, `menu_title_en`, `menu_title_nl`, `menu_title_ar`, `hero_title_en`, `hero_title_nl`, `hero_title_ar`, `hero_subtitle_en`, `hero_subtitle_nl`, `hero_subtitle_ar`, `hero_image`, `hero_cta_text_en`, `hero_cta_text_nl`, `hero_cta_text_ar`, `hero_cta_link`, `meta_title_en`, `meta_title_nl`, `meta_title_ar`, `meta_description_en`, `meta_description_nl`, `meta_description_ar`, `featured_image`, `og_title_en`, `og_title_nl`, `og_title_ar`, `og_description_en`, `og_description_nl`, `og_description_ar`, `og_image`, `twitter_title_en`, `twitter_title_nl`, `twitter_title_ar`, `twitter_description_en`, `twitter_description_nl`, `twitter_description_ar`, `created_at`) VALUES ('rev-6a26b05658083', 'page-about', 'About Us', '', 'من نحن', '<h3>Who We Are</h3><p>At <strong>Young Over 60</strong>, we believe that travel is not a luxury or a privilege reserved for a specific age group. Rather, it is a fundamental right for everyone, regardless of age or physical capabilities. It is a window to the beauty of the world, a gateway to connect with diverse cultures, and a vital source of physical and psychological well-being.</p><p>We are not just a travel travel news website; we are a vibrant, active platform specifically designed for those who believe that age is merely a number that should never define one\'s spirit or ambition. We firmly believe that real life begins after sixty—a time when experience expands, passion grows, and the desire to explore matures without limits.</p><blockquote>Our Slogan: Beyond 60, life Begins Again</blockquote><h3>Our Vision: Travel Without Limits</h3><p>We strive to make travel accessible, smooth, and enjoyable for everyone over sixty and for individuals with physical or sensory requirements. We work to break down the social stereotypes that label travel as difficult or unsuitable after a certain age or for individuals with determination. On the contrary, we see in you the energy of everlasting youth, and we want to be your trusted guide to exploring the world with safety, comfort, and luxury.</p><h3>What We Offer</h3><ul><li><strong>Specialized News & Analysis:</strong> The latest trends in accessible senior travel—from comfortable airline policies to hotels equipped with the highest standards of accessibility.</li><li><strong>In-Depth Travel Reports:</strong> Destinations ranked according to strict accessibility criteria, ease of movement, and availability of appropriate medical and recreational services.</li><li><strong>Stories & Inspiration:</strong> Real-life experiences of individuals who traveled beyond sixty or overcame physical challenges, proving that adventure knows no age and no barriers.</li><li><strong>Practical Guides & Tips:</strong> From planning your trip and dealing with international health insurance, to the best transportation options and accommodations tailored for your comfort.</li></ul><h3>Our Philosophy: Life Begins After Sixty</h3><p>We refuse to let a person be reduced to a number on a passport. Sixty is not the end of the road; it is a new departure point toward a life filled with discovery. Real youth is the vibrancy of the soul and the curiosity of the mind, and these never grow old.</p><p>At Young Over 60, we see in every traveler a story worth telling, and in every journey, an opportunity to renew life. Join us—because the world is too beautiful to be viewed only from a window, and because your right to travel never expires.</p>', NULL, '<h3>من نحن</h3><p>في <strong>Young Over 60</strong>، نؤمن بأن السياحة ليست ترفًا ولا رفاهية مخصصة لفئة عمرية معينة، بل هي حق أساسي للجميع، بغض النظر عن العمر أو القدرات الجسدية. هي نافذة على جمال العالم، ووسيلة للتواصل مع الثقافات، وداعم أساسي للصحة النفسية والجسدية.</p><p>نحن لسنا مجرد موقع سياحي إخباري؛ نحن منصة نابضة بالحياة، صممت خصيصًا لمن يرى أن العمر مجرد رقم لا يحدد الروح ولا الطموح. نؤمن بأن الحياة الحقيقية تبدأ بعد الستين، حيث تتسع الخبرة، ويزداد الشغف، وتنضج الرغبة في الاستكشاف دون قيود.</p><blockquote>شعارنا: Beyond 60, life Begins Again</blockquote><h3>رؤيتنا: سياحة بلا حدود</h3><p>نسعى لجعل تجربة السفر متاحة وميسرة وممتعة لكل من تجاوز الستين، ولكل فرد من ذوي الاحتياجات الخاصة. نعمل على كسر الصور النمطية التي تروّج أن السفر صعب أو غير مناسب بعد عمر معين، أو لأصحاب الهمم. بالعكس، نحن نرى فيكم طاقة الشباب المستمر، ونريد أن نكون دليلكم الموثوق لاستكشاف العالم بأمان ورقي.</p><h3>ماذا نقدم؟</h3><ul><li><strong>أخبار وتحليلات متخصصة:</strong> أحدث الاتجاهات في سياحة كبار السن وذوي الاحتياجات الخاصة، من سياسات الطيران المريحة إلى الفنادق المجهزة بأعلى المعايير.</li><li><strong>تقارير سياحية معمقة:</strong> وجهات مصنفة وفق معايير إمكانية الوصول (Accessibility)، وسهولة الحركة، وتوافر الخدمات الطبية والترفيهية المناسبة.</li><li><strong>قِصص وإلهام:</strong> تجارب حقيقية لأشخاص تجاوزوا الستين أو من ذوي الاحتياجات الخاصة، وأثبتوا أن المغامرة لا تعرف عمرًا ولا عائقًا.</li><li><strong>أدلة ونصائح عملية:</strong> من كيفية التخطيط للرحلة، والتعامل مع التأمين الصحي، إلى أفضل وسائل النقل والإقامة المصممة لراحتكم.</li></ul><h3>فلسفتنا: الحياة تبدأ بعد الستين</h3><p>نحن نرفض أن يُختزل الإنسان في رقم في جواز سفره. الستون ليست نهاية الطريق، بل هي محطة انطلاق جديدة نحو حياة مليئة بالاكتشافات. فالشباب الحقيقي هو نضارة الروح وفضول العقل، وهذان لا يشيخان أبدًا.</p><p>في Young Over 60، نرى في كل مسافر قصة تستحق أن تُروى، وفي كل رحلة فرصة لتجديد الحياة. انضم إلينا، لأن العالم أكبر من أن يُرى من النافذة فقط، ولأن حقك في السياحة لا يسقط بالتقادم.</p>', '', NULL, '', 'about-us', '1', '1', 'About Us', NULL, 'من نحن', 'About Us', NULL, 'من نحن', 'Beyond 60, life Begins Again', NULL, 'بعد الستين، تبدأ الحياة من جديد', '/images/australia.png', NULL, NULL, NULL, NULL, 'About Our Mission and Philosophy', NULL, 'من نحن ورسالتنا وسياستنا', 'Learn more about Young Over 60, our mission, vision, everlasting youth philosophy, and committed travel guidelines.', NULL, 'تعرف على رسالتنا ورؤيتنا وفلسفتنا في شباب فوق الستين نحو سياحة بلا حدود وخدمة أصحاب الهمم وكبار السن.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-06-08 22:06:46');
