  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `site_settings` (`id`, `siteName_en`, `siteName_nl`, `siteName_ar`, `logoUrl`, `logoDarkUrl`, `heroBackgroundUrl_en`, `heroBackgroundUrl_nl`, `heroBackgroundUrl_ar`, `metaTitle_en`, `metaTitle_nl`, `metaTitle_ar`, `metaDescription_en`, `metaDescription_nl`, `metaDescription_ar`, `metaKeywords_en`, `metaKeywords_nl`, `metaKeywords_ar`, `ogImage`, `faviconUrl`, `primaryColor`, `secondaryColor`, `accentColor`, `backgroundColor`, `textColor`, `surfaceColor`, `borderColor`, `themeMode`, `fontFamily`, `fontFamilyBody`, `fontFamilyAr`, `fontFamilyArBody`, `fontSize`, `headingWeight`, `bodyWeight`, `letterSpacing`, `lineHeight`, `nav_show_podcasts`, `nav_show_stories`, `nav_show_news`, `nav_show_accessibility`, `nav_show_contact`, `hero_mode`, `hero_video_en`, `hero_video_nl`, `hero_video_ar`, `hero_video_title_en`, `hero_video_title_nl`, `hero_video_title_ar`, `hero_video_subtitle_en`, `hero_video_subtitle_nl`, `hero_video_subtitle_ar`, `hero_video_btn_text_en`, `hero_video_btn_text_nl`, `hero_video_btn_text_ar`, `hero_video_btn_link`, `about_hero_label`, `about_hero_heading_line1`, `about_hero_heading_accent`, `about_hero_heading_line2`, `about_hero_quote`, `about_hero_desc`, `about_hero_desc_mobile`, `about_hero_btn1_text`, `about_hero_btn2_text`, `about_hero_badge_label`, `about_hero_badge_number`, `about_hero_image`, `about_vision_label`, `about_vision_heading`, `about_vision_heading_accent`, `about_vision_quote`, `about_vision_card1_title`, `about_vision_card1_text1`, `about_vision_card1_text2`, `about_vision_card2_title`, `about_vision_card2_text1`, `about_vision_card2_text2`, `about_stat1_number`, `about_stat1_desc`, `about_stat2_number`, `about_stat2_desc`, `about_stat3_number`, `about_stat3_desc`, `about_phili_label`, `about_phili_heading`, `about_phili_heading_accent`, `about_phili_quote`, `about_phili_text1`, `about_phili_text2`, `about_phili_text3`, `about_founder_name`, `about_founder_role`, `about_founder_linkedin`, `about_founder_quote`, `about_founder_image`, `about_contact_heading`, `about_contact_heading_accent`, `about_contact_desc`, `contact_whatsapp`, `contact_phone`, `updated_at`) VALUES ('1', 'Young Over 60', 'Travel Without Limits', NULL, '/uploads/0ba0846fbe81a15c_1781833074.png', '/uploads/534f400ba7cac412_1781833078.png', '/images/hero-bg.png', NULL, '/images/hero-bg.png', '', NULL, NULL, '', NULL, NULL, 'travel, young, traveler, egypt, young over 60, active travel, senior travel, accessible travel, youngover60.com', NULL, 'السفر, الشباب, مسافر, مصر, شباب فوق الستين, السفر النشط, سفر كبار السن, السياحة الميسرة, youngover60.com', NULL, '/uploads/37109696031bb94b_1781833084.png', '#0F4C81', '#1e3c5a', '#D4A75C', '#F8F6F2', '#1F1F1F', '#ffffff', 'rgba(0,0,0,0.05)', 'light', 'Outfit', 'Inter', 'Cairo', 'Cairo', '16px', '700', '400', 'normal', '1.8', '1', '0', '1', '0', '1', 'video', '/uploads/537dab8096dc49c0_1782828865.mp4', NULL, '/uploads/70fcc9bc260b8cde_1782828902.mp4', '', NULL, '', '', NULL, '', '', NULL, '', '', 'Our Story', 'Beyond', '60,', 'Life Begins Again.', 'Life Begins Again.', 'The stories, people, and passion behind a community that believes every new chapter can become the greatest adventure yet. We celebrate curiosity, connection, and meaningful journeys at every stage of life.', 'A community celebrating curiosity, connection, and meaningful journeys at every stage of life.', 'Discover Our Story →', 'Meet The Team', 'Stories Shared', '500+', '/assets/images/about-header.jpeg', 'About Young Over 60', 'Travel Has', 'No Age Limit', 'Beyond 60, life begins again.', 'Young Over 60', 'We believe that travel is neither a luxury nor a privilege reserved for a specific age group. It is a fundamental right for everyone, regardless of age or physical ability.', 'Travel opens windows to the world\'s beauty, creates connections between cultures, and contributes to both mental and physical wellbeing.', 'Our Vision: Travel Without Boundaries', 'We strive to make travel accessible, comfortable, and enjoyable for everyone over 60 and for individuals with special needs.', 'Our mission is to challenge outdated stereotypes and prove that adventure, curiosity, and exploration have no expiration date.', '60+', 'Celebrating life beyond traditional limits.', '∞', 'Endless opportunities to discover the world.', '100%', 'Dedicated to accessible and inclusive travel.', 'Our Philosophy', 'Life Begins', 'After 60', 'True youth lives in a curious mind and an adventurous spirit.', 'We reject the idea of reducing a person to the number on their passport. Sixty is not the end of the road—it is a new beginning, filled with opportunities for discovery, growth, and unforgettable experiences.', 'We believe that true youth is not measured by age, but by the ability to remain curious, open-minded, and eager to explore the world.', 'At Young Over 60, every traveller has a story worth telling and every journey is a chance to rediscover life. The world is far too beautiful to be viewed only from a window, and your right to travel never expires.', 'Zakaria Dawoud', 'Founder & Project CEO', 'https://www.linkedin.com/in/zakaria-dawoud-26902b180', 'Beyond 60, life begins again. This project was built to prove that travel has no age limit.', '/uploads/79e0afaa7d2a610d_1782519068.jpg', 'Let\'s Build Something', 'Meaningful', 'Whether you have a question, collaboration idea, or just want to say hello — feel free to reach out.', '+4917676503041', '+4917676503041', '2026-06-30 14:15:10');

DROP TABLE IF EXISTS `team_members`;
CREATE TABLE `team_members` (
  `id` varchar(36) NOT NULL,
  `name_en` varchar(255) NOT NULL,
  `name_nl` varchar(255) NOT NULL,
  `name_ar` varchar(255) DEFAULT NULL,
  `role_en` varchar(255) NOT NULL,
  `role_nl` varchar(255) NOT NULL,
  `role_ar` varchar(255) DEFAULT NULL,
  `bio_en` text DEFAULT NULL,
  `bio_nl` text DEFAULT NULL,
  `bio_ar` text DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `linkedin_url` varchar(255) DEFAULT NULL,
  `display_order` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `team_members` (`id`, `name_en`, `name_nl`, `name_ar`, `role_en`, `role_nl`, `role_ar`, `bio_en`, `bio_nl`, `bio_ar`, `image`, `linkedin_url`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('member-1', 'Mohamed Fahmy', '', 'محمد فهمي', 'Project manager', '', 'مدير مشاريع', 'Results-driven Technical Project Manager with extensive experience leading and delivering digital transformation and IT projects across diverse industries. Proven ability to manage cross-functional teams, coordinate stakeholders, and ensure successful project delivery within scope, schedule, and budget. Skilled in web technologies, cloud solutions, and enterprise systems, with a strong focus on process optimization, risk management, and business value delivery. Adept at translating complex technical requirements into actionable strategies while driving team performance and achieving organizational goals', NULL, 'مدير مشروعات تقني يتمتع بخبرة قوية في إدارة وتنفيذ المشاريع التقنية والتحول الرقمي، مع سجل حافل في قيادة فرق العمل متعددة التخصصات وضمان تسليم المشاريع في الوقت المحدد وضمن الميزانية المحددة. أمتلك خبرة واسعة في إدارة المشاريع الخاصة بالويب، الحوسبة السحابية، وأنظمة المؤسسات، مع التركيز على تحسين العمليات، إدارة أصحاب المصلحة، وضمان تحقيق أهداف الأعمال بكفاءة وجودة عالية. أتميز بمهارات قيادية وتنظيمية قوية وقدرة على تحويل المتطلبات التقنية المعقدة إلى حلول عملية تحقق قيمة حقيقية للعملاء والشركات', '/assets/images/founder.jpeg', 'https://www.linkedin.com/in/mohamedfahmyy?utm_source=share_via&utm_content=profile&utm_medium=member_android', '1', '1', '2026-06-22 00:45:11', '2026-06-27 00:19:07');

DROP TABLE IF EXISTS `testimonials`;
CREATE TABLE `testimonials` (
  `id` varchar(36) NOT NULL,
  `quote_en` text NOT NULL,
  `quote_nl` text NOT NULL,
  `quote_ar` text NOT NULL,
  `author_en` varchar(255) NOT NULL,
  `author_nl` varchar(255) NOT NULL,
  `author_ar` varchar(255) NOT NULL,
  `role_en` varchar(255) DEFAULT NULL,
  `role_nl` varchar(255) DEFAULT NULL,
  `role_ar` varchar(255) DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `testimonials` (`id`, `quote_en`, `quote_nl`, `quote_ar`, `author_en`, `author_nl`, `author_ar`, `role_en`, `role_nl`, `role_ar`, `image`, `created_at`) VALUES ('test-1', 'Young Over 60 transformed the way I travel. Their detailed reports on wheelchair accessibility in historic sites let me explore Giza with total confidence.', '', 'لقد غيّر موقع شباب فوق الستين طريقتي في السفر بالكامل. تقاريرهم الدقيقة والمفصلة حول سهولة حركة الكراسي المتحركة في المواقع الأثرية مكنتني من زيارة الجيزة بثقة تامة.', 'Sarah Jenkins', '', 'سارة جينكينز', 'Active Adventurer, UK', NULL, 'مغامرة نشطة، بريطانيا', '/uploads/admin-avatar.png', '2026-06-22 00:45:11');
INSERT INTO `testimonials` (`id`, `quote_en`, `quote_nl`, `quote_ar`, `author_en`, `author_nl`, `author_ar`, `role_en`, `role_nl`, `role_ar`, `image`, `created_at`) VALUES ('test-2', 'Finally, a luxury travel portal that treats accessibility as a core editorial theme rather than an afterthought. The recommendations are spot on!', '', 'أخيراً، بوابة سفر فاخرة تتعامل مع سهولة الوصول كفكرة تحريرية محورية وجوهرية وليست كفكرة ثانوية طارئة. توصياتهم في غاية الدقة!', 'Amina Mansour', '', 'أمينة منصور', 'Sensory Explorer, Egypt', NULL, 'مستكشفة حسية، مصر', '/uploads/admin-avatar.png', '2026-06-22 00:45:11');

