INSERT INTO `users` (`id`, `email`, `password`, `name`, `bio`, `avatar`, `twitter`, `facebook`, `instagram`, `linkedin`, `website`, `role`, `created_at`, `updated_at`) VALUES ('admin-uuid-1', 'admin@youngover60.com', '$2y$12$tanBCZuENAxM7yFBhzGIIeIJuZ9Cg0BmL2pqNp72WFRuIpD95ASRa', 'Site Admin', 'A passionate travel enthusiast dedicated to uncovering the world\'s most accessible gems. Sharing stories, tips, and guides to help everyone explore without limits.', '/uploads/admin-avatar.png', NULL, NULL, NULL, NULL, 'https://youngover60.com', 'ADMIN', '2026-06-22 00:45:11', '2026-06-22 00:45:11');

DROP TABLE IF EXISTS `women_stories`;
CREATE TABLE `women_stories` (
  `id` varchar(36) NOT NULL,
  `title_en` varchar(255) NOT NULL,
  `title_nl` varchar(255) NOT NULL,
  `title_ar` varchar(255) DEFAULT NULL,
  `slug_en` varchar(255) NOT NULL,
  `slug_nl` varchar(255) NOT NULL,
  `slug_ar` varchar(255) DEFAULT NULL,
  `excerpt_en` text DEFAULT NULL,
  `excerpt_nl` text DEFAULT NULL,
  `excerpt_ar` text DEFAULT NULL,
  `content_en` longtext NOT NULL,
  `content_nl` longtext NOT NULL,
  `content_ar` longtext DEFAULT NULL,
  `cover_image` varchar(255) DEFAULT NULL,
  `alt_text_en` varchar(255) DEFAULT NULL,
  `alt_text_nl` varchar(255) DEFAULT NULL,
  `alt_text_ar` varchar(255) DEFAULT NULL,
  `category_en` varchar(100) DEFAULT NULL,
  `category_nl` varchar(100) DEFAULT NULL,
  `category_ar` varchar(100) DEFAULT NULL,
  `author_en` varchar(255) DEFAULT NULL,
  `author_nl` varchar(255) DEFAULT NULL,
  `author_ar` varchar(255) DEFAULT NULL,
  `read_time` varchar(50) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug_en` (`slug_en`),
  UNIQUE KEY `slug_ar` (`slug_ar`),
  KEY `idx_stories_slug_en` (`slug_en`),
  KEY `idx_stories_slug_ar` (`slug_ar`),
  KEY `idx_stories_slug_nl` (`slug_nl`),
  FULLTEXT KEY `ft_stories_search_en` (`title_en`,`content_en`),
  FULLTEXT KEY `ft_stories_search_ar` (`title_ar`,`content_ar`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `women_stories` (`id`, `title_en`, `title_nl`, `title_ar`, `slug_en`, `slug_nl`, `slug_ar`, `excerpt_en`, `excerpt_nl`, `excerpt_ar`, `content_en`, `content_nl`, `content_ar`, `cover_image`, `alt_text_en`, `alt_text_nl`, `alt_text_ar`, `category_en`, `category_nl`, `category_ar`, `author_en`, `author_nl`, `author_ar`, `read_time`, `created_at`) VALUES ('story-1', 'Solo Travel Through Cairo: A Wheelchair User’s Journal', '', 'السفر المنفرد في القاهرة: يوميات مستخدمة كرسي متحرك', 'solo-travel-through-cairo-wheelchair-journal', '', 'يوميات-مسافرة-بكرسي-متحرك-في-القاهرة', 'A firsthand account of navigating Cairo\'s historic sites, bustling streets, and the pyramids using a mobility device.', NULL, 'تقرير شخصي عن استكشاف المواقع التاريخية في القاهرة، شوارعها المزدحمة، والأهرامات العظيمة باستخدام الأجهزة المساعدة وحلول سهولة الحركة.', '<h3>A Solo Wheelchair Traveler\'s Encounter with the Pyramids</h3><p>For as long as I can remember, the Pyramids of Giza were a distant dream locked behind an intimidating barrier of sand, stairs, and steep pathways. When I finally decided to embark on a solo trip to Cairo, my wheelchair was packed alongside a healthy dose of anxiety. However, what I discovered was a city eager to open its historic gates to everyone.</p><p>Entering the Giza Plateau with a custom ramp setup and the assistance of local guides who understood my physical needs, the monumental stone structures felt closer than ever. The dry air, the golden sandstone against the clear blue sky, and the sheer majesty of the Sphinx standing guard left me breathless. It was not just about the sites, but the warmth of the people. Everywhere I went, from the busy alleys of Khan el-Khalili to the spacious halls of the new Grand Egyptian Museum, locals went out of their way to ensure I had clear sightlines and easy access.</p><h4>Top 3 Accessibility Tips for Cairo:</h4><ul><li><strong>Hire an accessible-certified local driver:</strong> Cairo\'s traffic is legendary, and having a ramp-equipped van makes all the difference.</li><li><strong>Grand Egyptian Museum (GEM):</strong> This state-of-the-art facility is built to international ADA standards, featuring elevators, tactile maps, and spacious paths.</li><li><strong>Sunset at Giza:</strong> Watch the sunset from the accessible paved viewing platform near the panorama area. It offers a majestic view of all three pyramids without needing to cross deep sand.</li></ul>', '', '<h3>مسافرة منفردة بالكرسي المتحرك تلتقي بالأهرامات</h3><p>لطالما كانت أهرامات الجيزة حلماً بعيد المنال، يكتنفه الخوف من الرمال والدرج والمسارات الشديدة الانحدار. عندما قررت خوض هذه الرحلة إلى القاهرة، حزمت كرسيي المتحرك ومعي الكثير من القلق. ولكن، ما اكتشفته هو مدينة تفتح أبوابها التاريخية بكل ترحيب للجميع.</p><p>بمساعدة المنصات المهيأت والمرشدين المحليين اللذين تفهموا احتياجاتي الحركية، بدت الأهرامات الحجرية العملاقة أقرب من أي وقت مضى. نسيم الجو الجاف، وأحجار الجيزة الذهبية على خلفية السماء الزرقاء، ومهابة أبو الهول، كلها تفاصيل تركتني مندهشة. لم يكن الأمر يتعلق بالمواقع التاريخية فحسب، بل بدفء الناس؛ ففي كل مكان، من خان الخليلي إلى المتحف المصري الكبير، كان الجميع يبذلون قصارى جهدهم لضمان وضوح رؤيتي وسهولة حركتي.</p>', '/images/europe.png', NULL, NULL, NULL, 'Solo Travel', NULL, 'السفر المنفرد', 'Emily Watson', NULL, 'إميلي واتسون', '6 min read', '2026-06-22 00:45:11');
INSERT INTO `women_stories` (`id`, `title_en`, `title_nl`, `title_ar`, `slug_en`, `slug_nl`, `slug_ar`, `excerpt_en`, `excerpt_nl`, `excerpt_ar`, `content_en`, `content_nl`, `content_ar`, `cover_image`, `alt_text_en`, `alt_text_nl`, `alt_text_ar`, `category_en`, `category_nl`, `category_ar`, `author_en`, `author_nl`, `author_ar`, `read_time`, `created_at`) VALUES ('story-2', 'Navigating the Temples of Luxor with Sensory Needs', '', 'استكشاف معابد الأقصر بذوي الاحتياجات الحسية', 'navigating-temples-of-luxor-sensory-needs', '', 'معابد-الاقصر-وذوي-الاحتياجات-الحسية', 'Luxor\'s ancient monuments are awe-inspiring, but can be sensory-heavy. Here is a guide to finding quiet moments in Karnak Temple.', NULL, 'معالم الأقصر القديمة مذهلة، ولكنها قد تكون مزدحمة حسياً. إليك دليلك للعثور على لحظات الهدوء والسلام داخل معبد الكرنك.', '<h3>Luxor Temples: Navigating Sacred Spaces with Sensory Sensitivity</h3><p>The ruins of Luxor and Karnak Temples are visual spectacles, but their colossal scale, busy tour groups, and echoey columns can be overwhelming for travellers with sensory processing sensitivities. As a neurodivergent woman, my journey to Southern Egypt was a lesson in planning, presence, and finding silence within ancient stones.</p><p>I chose to visit the Karnak Temple complex at sunrise. Entering before the crowds, the great Hypostyle Hall felt like a quiet forest of stone. The early morning light cast soft shadows across the giant pillars, each carved with stories of pharaohs and gods. By timing my visits to coincide with typical lunch hours, I managed to explore the Luxor Temple in near solitude. It allowed me to appreciate the intricate hieroglyphics and connect with the spiritual history of the place without the sensory clutter of megaphones and chatter.</p><h4>My Recommendations for Sensory Balance:</h4><ul><li><strong>Noise-canceling headphones:</strong> Essential for busy entrance plazas and bazaar areas.</li><li><strong>Go early or late:</strong> Aim for 6:00 AM or 5:00 PM. Not only is the weather cooler, but the crowd level drops by 80%.</li><li><strong>Take a Felucca:</strong> A traditional sailboat ride on the Nile at sunset provides the perfect sensory reset after a long day of touring.</li></ul>', '', '<h3>معابد الأقصر: التنقل في المساحات المقدسة مع الحساسية الحسية</h3><p>أطلال معابد الأقصر والكرنك هي تحف بصرية رائعة، ولكن حجمها الضخم ومجموعاتها المزدحمة قد يسبب ضغطاً حسياً للمسافرين الذين يعانون من فرط الحساسية الحسية. كوني امرأة من ذوي الاختلاف العصبي، كانت رحلتي إلى جنوب مصر درساً في التخطيط والبحث عن الهدوء وسط الحجارة القديمة.</p><p>اخترت زيارة مجمع معابد الكرنك عند شروق الشمس. بالدخول قبل بدء المجموعات السياحية، بدت قاعة الأعمدة الكبرى كغابة هادئة من الحجر. ألقى ضوء الصباح الباكر ظلالاً ناعمة على الأعمدة الضخمة، المنقوشة بقصص الفراعنة والآلهة. بتنسيق أوقات الزيارة لتتزامن مع وقت الغداء السياحي المعتاد، تمكنت من استكشاف معبد الأقصر في هدوء تام.</p>', '/images/australia.png', NULL, NULL, NULL, 'Accessible Adventure', NULL, 'مغامرة ميسرة', 'Sarah Jenkins', NULL, 'سارة جينكينز', '5 min read', '2026-06-22 00:45:11');
INSERT INTO `women_stories` (`id`, `title_en`, `title_nl`, `title_ar`, `slug_en`, `slug_nl`, `slug_ar`, `excerpt_en`, `excerpt_nl`, `excerpt_ar`, `content_en`, `content_nl`, `content_ar`, `cover_image`, `alt_text_en`, `alt_text_nl`, `alt_text_ar`, `category_en`, `category_nl`, `category_ar`, `author_en`, `author_nl`, `author_ar`, `read_time`, `created_at`) VALUES ('story-3', 'A Deaf Traveller’s Guide to the Vibrant Bazaars of Khan el-Khalili', '', 'دليل المسافرة الكفيفة إلى أسواق خان الخليلي المزدحمة', 'deaf-traveller-guide-khan-el-khalili', '', 'دليل-المسافرة-الكفيفة-خان-الخليلي', 'Exploring the sights, smells, and textures of Cairo\'s famous marketplace through the lens of visual and tactile connection.', NULL, 'استكشاف المناظر والروائح والأقمشة في أشهر أسواق القاهرة القديمة من منظور التواصل البصري الحسي واللمسي الفريد.', '<h3>Sounds and Scents of Cairo: A Blind Traveler\'s Perspective</h3><p>Most travel brochures focus on the sights of Egypt, but the true essence of Cairo lies in its auditory and olfactory landscape. Exploring the historic Islamic Cairo as a blind woman opened my senses to a symphony of sights unheard and textures unfelt.</p><p>Navigating the medieval gates of Bab Zuwayla, the air smelled of roasted cardamom, fresh mint, and the rich earthy scent of tanned leather. Walking through Al-Muizz Street, the voice of the muezzin calling for prayer echoed from towering minarets, wrapping the ancient street in a blanket of peace. Hand-carved brass lamps felt cold and detailed under my fingertips, and the warmth of a freshly baked Aish Baladi (Egyptian flatbread) handed to me by a smiling baker was a moment of pure connection. Cairo does not require sight to be seen; it demands that you listen, smell, and touch.</p><h4>Key Insights for Visually Impaired Visitors:</h4><ul><li><strong>Tactile exploration:</strong> Many museums allow supervised touching of selected replica statues. Always ask for \'tactile guides\'.</li><li><strong>Scent mapping:</strong> Khan el-Khalili\'s spice section is a wonderful sensory journey. Local merchants are proud to let you sample incense, spices, and perfumes.</li><li><strong>Companion guides:</strong> Work with specialized operators who are trained in descriptive narration of architectural details.</li></ul>', '', '<h3>روائح وأصوات القاهرة: منظور مسافرة كفيفة</h3><p>تركز معظم الكتيبات السياحية على المشاهد المرئية، لكن الجوهر الحقيقي للقاهرة يكمن في أصواتها وروائحها الفريدة. استكشاف القاهرة الإسلامية كمسافرة كفيفة فتح حواسي على سمفونية متناغمة من الروائح التي لا نراها والملامس التي نتحسسها.</p><p>عند المشي بجوار بوابة باب زويلة، تفوح في الهواء رائحة الهيل المحمص والنعناع الطازج ورائحة الجلود العتيقة الدافئة. وخلال السير في شارع المعز، يتردد صدى صوت المؤذن داعياً للصلاة من المآذن الشاهقة، ليغمر الشارع القديم بعباءة من السلام والسكينة. مصابيح النحاس المنقوشة يدوياً كانت باردة ومليئة بالتفاصيل تحت أطراف أصابعي.</p>', '/images/hero-bg.png', NULL, NULL, NULL, 'Cultural Journeys', NULL, 'رحلات ثقافية', 'Amina Mansour', NULL, 'أمينة منصور', '7 min read', '2026-06-22 00:45:11');

